{
  "packet_id": "H6-T02-2",
  "claim_id": "C061",
  "status": "SUPPORTED",
  "claim": {
    "component_id": "C061",
    "value": "Worker version, workload and overnight load may be confounded.",
    "scope": "A possible relation among comparison factors, not a finding that particular factors are confounded.",
    "provenance": {
      "refs": [
        {
          "source_id": "P029",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P029 explicitly identifies these factors and the possibility of confounding."
    }
  },
  "signal_basis": {
    "component_id": "C061_SIGNAL",
    "value": "Compare exports within similar workloads, execution windows and worker versions, repeat comparisons by version and workload, and assess whether version associations persist or disappear after accounting for coverage or workload.",
    "scope": "A proposed comparative investigation whose associations may be sensitive to the comparison factors; it does not establish that confounding actually occurs.",
    "provenance": {
      "refs": [
        {
          "source_id": "P006",
          "role": "SUPPORT"
        },
        {
          "source_id": "P011",
          "role": "SUPPORT"
        },
        {
          "source_id": "P020",
          "role": "SUPPORT"
        },
        {
          "source_id": "P021",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The cited spans supply the comparison procedure, sensitivity assessment and explicit qualification that these observations are proposed."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C061_RELATION",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "No unresolved empirical relation is required to warrant this possibility claim."
    }
  },
  "rationale": "The comparison does not guarantee that worker version, workload and overnight load vary independently. Their possible confounding is therefore a warranted limitation, even when execution prerequisites are met and the comparative signal occurs. The claim asserts only this possibility.",
  "uncertainty": "Whether these factors actually are confounded, and how strongly, remains unestablished; neither is asserted by the frozen claim.",
  "anomalies": []
}
